#include <algorithm>
#include <cstdint>
#include <iostream>
#include <numeric>
#include <vector>
using namespace std;
vector<long long> profiles(const vector<unsigned>&T){unsigned n=T.size();vector<unsigned>w(n);iota(w.begin(),w.end(),0);long long C[8][8]={};for(unsigned i=0;i<=n;i++){C[i][0]=1;for(unsigned j=1;j<=i;j++)C[i][j]=C[i-1][j-1]+C[i-1][j];}vector<long long>q(n+1);do{unsigned bad=0;for(unsigned i=0;i+1<n;i++)bad+=!(T[w[i]]>>w[i+1]&1);for(unsigned t=0;t<=n-1-bad;t++)q[1+bad+t]+=C[n-1-bad][t];}while(next_permutation(w.begin(),w.end()));return q;}
vector<unsigned> core(unsigned n,unsigned code){vector<unsigned>T(n);unsigned k=0;for(unsigned u=0;u<n;u++)for(unsigned v=u+1;v<n;v++,k++){if(code>>k&1)T[u]|=1u<<v;else T[v]|=1u<<u;}return T;}
vector<unsigned> attach(vector<unsigned>T,unsigned a,unsigned c){unsigned n=T.size();T.resize(n+2);T[n]=1u<<(n+1);T[n+1]=0;for(unsigned u=0;u<n;u++){if(a>>u&1)T[u]|=1u<<n;else T[n]|=1u<<u;if(c>>u&1)T[u]|=1u<<(n+1);else T[n+1]|=1u<<u;}return T;}
int main(){uint64_t tournaments=0,queries=0,coefficients=0,nonzero=0;for(unsigned n=1;n<=4;n++){unsigned nt=1u<<(n*(n-1)/2),N=1u<<n;vector<vector<vector<long long>>>bank(nt,vector<vector<long long>>(N*N));for(unsigned code=0;code<nt;code++){auto T=core(n,code);tournaments++;for(unsigned a=0;a<N;a++)for(unsigned c=0;c<N;c++){bank[code][a*N+c]=profiles(attach(T,a,c));queries++;}}auto coeff=[&](unsigned code,unsigned a,unsigned c,unsigned h){long long z=0;for(unsigned s=a;;s=(s-1)&a){for(unsigned t=c;;t=(t-1)&c){z+=(__builtin_popcount(s)+__builtin_popcount(t))%2?-bank[code][s*N+t][h]:bank[code][s*N+t][h];if(!t)break;}if(!s)break;}return z;};for(unsigned code=0;code<nt;code++)for(unsigned a=0;a<N;a++)if(__builtin_popcount(a)==2)for(unsigned c=0;c<N;c++)if(__builtin_popcount(c)==2)for(unsigned h=1;h<=n+2;h++){long long x=coeff(code,a,c,h),y=coeff(nt-1-code,a,c,h);if(x!=y){cerr<<"whole-converse q quartic mismatch\n";return 2;}if(x<0){cerr<<"negative individual quartic\n";return 3;}coefficients++;nonzero+=(x!=0);}}cout<<"{\"status\":\"PASS\",\"old_tournaments\":"<<tournaments<<",\"actual_word_cut_profile_queries\":"<<queries<<",\"profile_quartic_coordinates\":"<<coefficients<<",\"nonzero_profile_coordinates\":"<<nonzero<<"}\n";}
